/**
 * Manage — OpenCode Management Plugin (M1 + M1g + M1i + M1r: airlock gate + proposals + groups + impact + registry write channel)
 *
 * Core principle: STRUCTURAL, not heuristic. There is no path from the AI
 * to the filesystem. The gate denies the mutation tools outright; the AI's
 * only "write" channels are emit_proposal and registry_propose, which write
 * nothing to disk — they append to review queues the user applies.
 *
 * Fail-closed: if the project's `.opencode/manage.rules.json` is missing,
 * the airlock defaults to ON (all mutations denied). A rules file can
 * whitelist specific tools.
 *
 * Rules file shape (per project, .opencode/manage.rules.json):
 * {
 *   "deny": ["bash", "edit", "write", "patch"],   // default if absent
 *   "allow": []                                    // exact tool names that override deny
 * }
 *
 * NOTE: `bash` is denied even when a rules file forgets it — it can write
 * files directly (echo >, rm, mv) and no hook can see inside its effects.
 *
 * group (M1g): every proposal carries a short slug tying it to one logical
 * change across N files ("add-metrics-service"). Groups enable grouped
 * review and revert-by-group in the nvim side. See
 * ~/docs/opencode/manage-plugin/03-proposals.md.
 *
 * impact (M1i): every proposal targeting a registered SHARED module must
 * carry an `impact` list — real consumers/symbols gathered via LSP before
 * proposing — so changing central logic never happens blind. Shared modules
 * live in the per-project `.opencode/manage.registry.json` (fail-open: no
 * registry file = no impact requirement). See
 * ~/docs/opencode/manage-plugin/17-impact-registry.md.
 *
 * registry_propose (M1r): the registry's WRITE channel. The AI submits new
 * shared / canonical / modularize / consolidations entries to a pending
 * queue (`.opencode/manage.registry.pending.jsonl`); the user reviews and
 * merges them via the nvim console. The registry grows through review, not
 * by hand. Entries are validated structurally (paths exist on disk, shape,
 * duplicates) before they reach the queue.
 *
 * DENIAL IS TERMINAL: the throw messages below explicitly tell the model
 * not to retry or work around a denied tool. Retry-thrash (deny → retry →
 * deny) burns model rounds and drifts the conversation; the message kills
 * it at the source. The impact requirement and registry_propose validation
 * are the ONE deliberate exception: their errors are REQUIREMENTS retries —
 * the model must fix the input (run LSP, correct the shape) and re-emit,
 * not give up.
 */

import { type Plugin, tool } from "@opencode-ai/plugin";
import { mkdirSync, appendFileSync, readFileSync, existsSync } from "fs";
import { join, dirname, isAbsolute } from "path";

// ── Gate: deny mutation tools at the hook level ────────────────────────────

// Default deny-list when no rules file exists (fail-closed airlock).
const DEFAULT_DENY = ["bash", "edit", "write", "patch", "apply_patch"];

function loadRules(directory: string): { deny: string[]; allow: string[] } {
  const rulesPath = join(directory, ".opencode", "manage.rules.json");
  try {
    const parsed = JSON.parse(readFileSync(rulesPath, "utf8"));
    return {
      deny: Array.isArray(parsed.deny) ? parsed.deny : DEFAULT_DENY,
      allow: Array.isArray(parsed.allow) ? parsed.allow : [],
    };
  } catch {
    // No rules file (or unreadable) → fail closed to the default airlock.
    return { deny: DEFAULT_DENY, allow: [] };
  }
}

// ── Registry: shared-logic awareness (M1i + M1r, fail-open) ────────────────

interface RefEntry {
  path: string;
  symbol?: string;
  relation?: string;
}

interface RegistryEntry {
  path?: string;
  symbols?: string[];
  fragile?: boolean;
  constraints?: string;
  rationale?: string;
  refs?: RefEntry[];
}

interface CanonicalEntry {
  concept?: string;
  path?: string;
  symbols?: string[];
  rationale?: string;
  refs?: RefEntry[];
}

interface ModularizeEntry {
  path?: string;
  symbols?: string[];
  rationale?: string;
}

interface ConsolidationEntry {
  paths?: string[];
  rationale?: string;
  suggested_target?: string;
}

interface Registry {
  shared: RegistryEntry[];
  canonical: CanonicalEntry[];
  modularize: ModularizeEntry[];
  consolidations: ConsolidationEntry[];
}

const EMPTY_REGISTRY: Registry = {
  shared: [],
  canonical: [],
  modularize: [],
  consolidations: [],
};

function loadRegistry(directory: string): Registry {
  const registryPath = join(directory, ".opencode", "manage.registry.json");
  try {
    const parsed = JSON.parse(readFileSync(registryPath, "utf8"));
    return {
      shared: Array.isArray(parsed.shared) ? parsed.shared : [],
      canonical: Array.isArray(parsed.canonical) ? parsed.canonical : [],
      modularize: Array.isArray(parsed.modularize) ? parsed.modularize : [],
      consolidations: Array.isArray(parsed.consolidations) ? parsed.consolidations : [],
    };
  } catch {
    // No registry file → fail open: no shared modules registered.
    return EMPTY_REGISTRY;
  }
}

// Exact path match, or anything nested under the shared path.
function matchesSharedPath(shared: RegistryEntry[], targetPath: string): RegistryEntry | null {
  const norm = targetPath.replace(/^\.\//, "");
  for (const entry of shared) {
    if (!entry.path) continue;
    const p = entry.path.replace(/^\.\//, "").replace(/\/+$/, "");
    if (norm === p || norm.startsWith(p + "/")) return entry;
  }
  return null;
}

function buildRegistrySummary(directory: string): string {
  const reg = loadRegistry(directory);
  const lines: string[] = [];
  for (const s of reg.shared) {
    const symbols = s.symbols && s.symbols.length ? s.symbols.join(", ") : "shared logic";
    const fragile = s.fragile ? " [FRAGILE]" : "";
    const constraints = s.constraints ? ` constraints: ${s.constraints}` : "";
    lines.push(`- ${s.path}${fragile} — ${symbols};${constraints}`);
  }
  for (const c of reg.canonical) {
    const symbols = c.symbols && c.symbols.length ? ` (${c.symbols.join(", ")})` : "";
    lines.push(`- ${c.concept}: reuse ${c.path}${symbols} — do not reimplement`);
  }
  for (const m of reg.modularize) {
    const symbols = m.symbols && m.symbols.length ? ` (${m.symbols.join(", ")})` : "";
    lines.push(
      `- MODULARIZE: ${m.path}${symbols} — ${m.rationale || "repeated code; candidate for extraction"}`,
    );
  }
  for (const c of reg.consolidations) {
    const paths = (c.paths || []).join(", ");
    lines.push(
      `- CONSOLIDATE: ${paths} — ${c.rationale || "similar implementations; merge candidate"}` +
        (c.suggested_target ? ` → ${c.suggested_target}` : ""),
    );
  }
  if (!lines.length) return "";
  return "\n\nProject shared-logic registry (.opencode/manage.registry.json):\n" + lines.join("\n");
}

// ── Registry pending queue (M1r write channel) ─────────────────────────────

interface PendingEntry {
  ts: number;
  sessionID: string;
  kind: string;
  path: string | null;
  paths: string[];
  status: string;
}

function registryPendingFile(directory: string): string {
  return join(directory, ".opencode", "manage.registry.pending.jsonl");
}

function loadPending(directory: string): PendingEntry[] {
  try {
    const raw = readFileSync(registryPendingFile(directory), "utf8");
    return raw
      .split("\n")
      .filter(Boolean)
      .map((line) => {
        try {
          return JSON.parse(line) as PendingEntry;
        } catch {
          return null;
        }
      })
      .filter((e): e is PendingEntry => e !== null);
  } catch {
    return [];
  }
}

function appendPending(directory: string, sessionID: string, entry: unknown) {
  const file = registryPendingFile(directory);
  mkdirSync(dirname(file), { recursive: true });
  appendFileSync(file, JSON.stringify(entry) + "\n", "utf8");
}

const REGISTRY_KINDS = ["shared", "canonical", "modularize", "consolidations"] as const;

// Duplicate-detection key: the path for single-path kinds, the sorted path
// set for consolidations.
function entryKey(kind: string, path: string | null, paths: string[]): string {
  return kind === "consolidations" ? [...paths].sort().join("|") : path || "";
}

function entryExists(directory: string, kind: string, key: string): boolean {
  const reg = loadRegistry(directory);
  let inRegistry = false;
  if (kind === "shared") inRegistry = reg.shared.some((e) => entryKey(kind, e.path || "", []) === key);
  else if (kind === "canonical") inRegistry = reg.canonical.some((e) => entryKey(kind, e.path || "", []) === key);
  else if (kind === "modularize") inRegistry = reg.modularize.some((e) => entryKey(kind, e.path || "", []) === key);
  else if (kind === "consolidations") inRegistry = reg.consolidations.some((e) => entryKey(kind, null, e.paths || []) === key);
  if (inRegistry) return true;
  return loadPending(directory).some(
    (p) => p.kind === kind && entryKey(kind, p.path, p.paths || []) === key,
  );
}

// ── Shared arg parsing (JSON strings, same pattern as impact/reuses) ───────

function parseStringList(raw: string | undefined, label: string): string[] {
  if (!raw || raw.trim() === "") return [];
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new Error(
      `[manage] ⚠️ "${label}" must be a JSON array of strings — it failed to parse. Re-emit.`,
    );
  }
  if (!Array.isArray(parsed)) {
    throw new Error(
      `[manage] ⚠️ "${label}" must be a JSON array of strings — got ${typeof parsed}. Re-emit.`,
    );
  }
  const out: string[] = [];
  for (const item of parsed) {
    if (typeof item !== "string" || item.trim() === "") {
      throw new Error(`[manage] ⚠️ Every "${label}" entry must be a non-empty string. Re-emit.`);
    }
    out.push(item.trim());
  }
  return out;
}

function parseRefs(directory: string, raw: string): RefEntry[] {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new Error(
      `[manage] ⚠️ "refs" must be a JSON array of {"path","symbol","relation"} objects — ` +
        `it failed to parse. Run lsp_find_references on the symbols and re-emit.`,
    );
  }
  if (!Array.isArray(parsed)) {
    throw new Error(`[manage] ⚠️ "refs" must be a JSON array — got ${typeof parsed}. Re-emit.`);
  }
  const entries: RefEntry[] = [];
  for (const item of parsed) {
    if (!item || typeof item.path !== "string") {
      throw new Error(`[manage] ⚠️ Every "refs" entry needs a string "path". Re-emit.`);
    }
    const target = isAbsolute(item.path) ? item.path : join(directory, item.path);
    if (!existsSync(target)) {
      throw new Error(
        `[manage] ⚠️ Refs path "${item.path}" does not exist on disk — refs must come from real ` +
          `lsp_find_references results, not invention. Re-run the LSP queries and re-emit.`,
      );
    }
    entries.push({
      path: item.path,
      symbol: typeof item.symbol === "string" ? item.symbol : undefined,
      relation: typeof item.relation === "string" ? item.relation : "referenced-by",
    });
  }
  return entries;
}

// ── Impact: structural requirement before touching shared code ─────────────

interface ImpactEntry {
  path: string;
  symbol: string;
  relation: string;
}

function parseImpact(directory: string, raw: string): ImpactEntry[] {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new Error(
      `[manage] ⚠️ "impact" must be a JSON array of {"path","symbol","relation"} objects — ` +
        `it failed to parse. Run lsp_find_references on the symbols you are changing and re-emit.`,
    );
  }
  if (!Array.isArray(parsed)) {
    throw new Error(
      `[manage] ⚠️ "impact" must be a JSON array — got ${typeof parsed}. Re-emit with a valid impact list.`,
    );
  }
  const entries: ImpactEntry[] = [];
  for (const item of parsed) {
    if (!item || typeof item.path !== "string" || typeof item.symbol !== "string") {
      throw new Error(
        `[manage] ⚠️ Every "impact" entry needs a string "path" and a string "symbol". Re-emit.`,
      );
    }
    const target = isAbsolute(item.path) ? item.path : join(directory, item.path);
    if (!existsSync(target)) {
      throw new Error(
        `[manage] ⚠️ Impact path "${item.path}" does not exist on disk — impact must come from real ` +
          `lsp_find_references results, not invention. Re-run the LSP queries and re-emit.`,
      );
    }
    entries.push({
      path: item.path,
      symbol: item.symbol,
      relation: typeof item.relation === "string" ? item.relation : "referenced-by",
    });
  }
  return entries;
}

function impactRequiredMessage(path: string): string {
  return (
    `[manage] ⚠️ Proposal for "${path}" touches a registered SHARED module, so it needs a valid ` +
    `"impact" list. Run lsp_find_references (and lsp_goto_definition) on the symbols you are ` +
    `changing, then re-emit emit_proposal with "impact" as a JSON array of ` +
    `{"path","symbol","relation"} entries. Every path must exist on disk. ` +
    `This is a REQUIREMENTS retry — the proposal is NOT recorded until impact is valid.`
  );
}

// ── Proposals: the AI's only code "write" channel ──────────────────────────

function proposalsFile(directory: string, sessionID: string): string {
  return join(directory, ".ai-proposals", `${sessionID}.jsonl`);
}

function appendProposal(
  directory: string,
  sessionID: string,
  proposal: unknown,
) {
  const file = proposalsFile(directory, sessionID);
  mkdirSync(dirname(file), { recursive: true });
  appendFileSync(file, JSON.stringify(proposal) + "\n", "utf8");
}

export const ManagePlugin: Plugin = async ({ directory }) => {
  return {
    // ── Airlock gate: runs before EVERY tool call ────────────────────────
    "tool.execute.before": async (input) => {
      const rules = loadRules(directory);
      const toolName = input.tool;

      // Explicit allow wins.
      if (rules.allow.includes(toolName)) {
        return;
      }
      if (rules.deny.includes(toolName)) {
        throw new Error(
          `[manage] ❌ Tool "${toolName}" is DENIED by the airlock — ` +
            `permanently, do not retry it or attempt a workaround. ` +
            `The AI cannot mutate the filesystem. Use emit_proposal instead.`,
        );
      }
      // bash is denied by default even if a rules file forgot it.
      if (toolName === "bash" && !rules.allow.includes("bash")) {
        throw new Error(
          `[manage] ❌ bash is DENIED by the airlock — permanently, do not ` +
            `retry it or attempt a workaround. The AI cannot run shell ` +
            `commands. Propose changes with emit_proposal; the user runs commands.`,
        );
      }
    },

    tool: {
      // ── The only code write channel: structured proposal ──────────────
      emit_proposal: tool({
        description:
          "Propose a file change for the user to review and apply manually. " +
          "This tool writes NOTHING to disk — it records a structured proposal " +
          "the user accepts or rejects. This is your ONLY write channel: " +
          "bash/edit/write/patch are permanently denied, so do not attempt them. " +
          "For a task touching multiple files, call this once per file and give " +
          "every call the same `group` slug so the change stays reviewable and " +
          "revertible as one unit. " +
          "Before proposing changes to any shared/central module, run " +
          "lsp_find_references on the symbols you will change and populate " +
          "`impact` with the real consumers." +
          buildRegistrySummary(directory),
        args: {
          path: tool.schema
            .string()
            .describe("Absolute or project-relative file path to change"),
          operation: tool.schema
            .string()
            .describe(
              "Type of change: 'create' (new file), 'replace' (full-file), " +
                "'edit_range' (replace lines start_line..end_line), 'delete'",
            ),
          content: tool.schema
            .string()
            .describe(
              "Full new file content (for create/replace) or the replacement block",
            ),
          reason: tool.schema
            .string()
            .describe("Why this change — so the user can review intent"),
          group: tool.schema
            .string()
            .describe(
              "Short slug tying this proposal to one logical change across files " +
                "(e.g. 'add-metrics-service'). All files of one task share one group.",
            ),
          start_line: tool.schema
            .string()
            .describe(
              "For edit_range: first line to replace (1-based). Empty string if unused.",
            ),
          end_line: tool.schema
            .string()
            .describe(
              "For edit_range: last line to replace (1-based). Empty string if unused.",
            ),
          impact: tool.schema
            .string()
            .describe(
              'JSON array of impact entries — REQUIRED when the target path is a ' +
                'registered shared module. Each entry: {"path": string, "symbol": string, ' +
                '"relation": string}. Gather via lsp_find_references / ' +
                "lsp_goto_definition before proposing. Every path must exist on disk.",
            ),
          reuses: tool.schema
            .string()
            .describe(
              'Optional: canonical implementations this change reuses, to prove no ' +
                'duplication. JSON array of {"path": string, "symbol": string}. ' +
                "Prefer the registry's canonical entries over reimplementing.",
            ),
        },
        async execute(args, context) {
          const sessionID = context.sessionID;
          const registry = loadRegistry(directory);
          const sharedHit = matchesSharedPath(registry.shared, args.path);

          // Structural impact requirement: touching a shared module without
          // evidence of what it affects is a REQUIREMENTS error, not a denial.
          let impact: ImpactEntry[] = [];
          if (sharedHit && (!args.impact || args.impact.trim() === "")) {
            throw new Error(impactRequiredMessage(args.path));
          }
          if (args.impact && args.impact.trim() !== "") {
            impact = parseImpact(directory, args.impact);
          }

          const proposal = {
            ts: Date.now(),
            sessionID,
            group: args.group || "misc",
            path: args.path,
            operation: args.operation,
            reason: args.reason,
            start_line: args.start_line ? parseInt(args.start_line, 10) : null,
            end_line: args.end_line ? parseInt(args.end_line, 10) : null,
            content: args.content,
            impact,
            reuses: args.reuses || null,
            status: "pending", // pending | accepted | rejected (user/nvim sets this)
          };
          appendProposal(directory, sessionID, proposal);
          return JSON.stringify(
            {
              ok: true,
              message:
                `Proposal recorded (${args.operation}) for ${args.path} ` +
                `[group: ${proposal.group}, impact: ${impact.length} ` +
                `${impact.length === 1 ? "entry" : "entries"}]. ` +
                `Nothing was written. The user must apply it manually.`,
              proposal_id: proposal.ts,
              manifest: proposalsFile(directory, sessionID),
            },
            null,
            2,
          );
        },
      }),

      // ── Registry write channel (M1r): submit entries through review ────
      registry_propose: tool({
        description:
          "Submit a registry entry for review — the write channel for the project's " +
          "shared-logic registry (.opencode/manage.registry.json). Use this when you " +
          "notice duplicated logic, a reusable pattern, or a change touching " +
          "central/shared code: the registry is how this project avoids reinventing " +
          "the wheel. " +
          "This tool writes NOTHING to the registry — it appends to a pending queue " +
          "the user reviews and merges. " +
          "kinds: 'shared' (central module — future proposals touching it will require " +
          "impact), 'canonical' (concept → implementation to reuse; needs 'concept'), " +
          "'modularize' (repeated code that should be extracted into a module), " +
          "'consolidations' (2+ similar paths that could merge; needs 'paths'). " +
          "Run lsp_goto_definition / lsp_find_references on the symbols first and record " +
          "the real usage sites in 'refs'. Every path must exist on disk. " +
          "Validation errors are REQUIREMENTS retries — fix the input and re-emit." +
          buildRegistrySummary(directory),
        args: {
          kind: tool.schema
            .string()
            .describe("'shared' | 'canonical' | 'modularize' | 'consolidations'"),
          path: tool.schema
            .string()
            .describe(
              "Project-relative path to the module (shared/canonical/modularize). Empty for consolidations.",
            ),
          paths: tool.schema
            .string()
            .describe(
              "For consolidations only: JSON array of 2+ existing project-relative paths. Empty otherwise.",
            ),
          symbols: tool.schema
            .string()
            .describe(
              'JSON array of symbol names — REQUIRED for shared and canonical. ' +
                "Verify each resolves via lsp_goto_definition first.",
            ),
          concept: tool.schema
            .string()
            .describe(
              "For canonical only: the concept this implementation is the canonical " +
                "answer for (e.g. 'time formatting').",
            ),
          rationale: tool.schema
            .string()
            .describe("WHY this entry belongs in the registry — shown in the summary MD."),
          refs: tool.schema
            .string()
            .describe(
              'Optional: JSON array of {"path","symbol","relation"} usage sites gathered ' +
                "via lsp_find_references. Every path must exist on disk.",
            ),
          fragile: tool.schema
            .string()
            .describe(
              "For shared only: 'true' or 'false' — marks high-risk central logic [FRAGILE].",
            ),
          constraints: tool.schema
            .string()
            .describe(
              "For shared only: rules the model must follow when touching this module " +
                "(e.g. 'additive changes only').",
            ),
          suggested_target: tool.schema
            .string()
            .describe(
              "For consolidations only: the proposed merged target path (optional).",
            ),
          group: tool.schema
            .string()
            .describe("Optional M1g slug tying this entry to a task group."),
        },
        async execute(args, context) {
          const sessionID = context.sessionID;
          const kind = (args.kind || "").trim();
          if (!(REGISTRY_KINDS as readonly string[]).includes(kind)) {
            throw new Error(
              `[manage] ⚠️ registry_propose "kind" must be one of: ${REGISTRY_KINDS.join(", ")}. Re-emit.`,
            );
          }
          if (!args.rationale || args.rationale.trim() === "") {
            throw new Error(
              '[manage] ⚠️ registry_propose needs "rationale" — the WHY that shows in the summary. Re-emit.',
            );
          }

          const path = (args.path || "").trim();
          let paths: string[] = [];
          if (kind === "consolidations") {
            paths = parseStringList(args.paths, "paths");
            if (paths.length < 2) {
              throw new Error(
                '[manage] ⚠️ "consolidations" needs "paths" with at least 2 existing files. Re-emit.',
              );
            }
          } else {
            if (!path) {
              throw new Error(
                `[manage] ⚠️ registry_propose for kind "${kind}" needs "path". Re-emit.`,
              );
            }
            paths = [path];
          }

          // Every target must exist on disk — no invented entries.
          for (const p of paths) {
            const target = isAbsolute(p) ? p : join(directory, p);
            if (!existsSync(target)) {
              throw new Error(
                `[manage] ⚠️ Path "${p}" does not exist on disk — registry entries must target real code. Re-emit.`,
              );
            }
          }

          const symbols = parseStringList(args.symbols, "symbols");
          if ((kind === "shared" || kind === "canonical") && symbols.length === 0) {
            throw new Error(
              `[manage] ⚠️ kind "${kind}" needs "symbols" — the entry names the actual symbols. Re-emit.`,
            );
          }
          if (kind === "canonical" && (!args.concept || args.concept.trim() === "")) {
            throw new Error(
              '[manage] ⚠️ kind "canonical" needs "concept" — the concept this implementation is canonical for. Re-emit.',
            );
          }

          let refs: RefEntry[] = [];
          if (args.refs && args.refs.trim() !== "") {
            refs = parseRefs(directory, args.refs);
          }

          let fragile = false;
          if (args.fragile && args.fragile.trim() !== "") {
            if (args.fragile.trim() === "true") fragile = true;
            else if (args.fragile.trim() !== "false") {
              throw new Error('[manage] ⚠️ "fragile" must be "true" or "false". Re-emit.');
            }
          }

          // Duplicate detection against the registry AND the pending queue.
          const key = entryKey(kind, path, paths);
          if (entryExists(directory, kind, key)) {
            throw new Error(
              `[manage] Entry "${key}" (${kind}) is already registered or pending — ` +
                "no re-emit needed; the registry already covers it.",
            );
          }

          const entry = {
            ts: Date.now(),
            sessionID,
            kind,
            path: kind === "consolidations" ? null : path,
            paths: kind === "consolidations" ? paths : [],
            symbols,
            concept: kind === "canonical" ? args.concept.trim() : null,
            rationale: args.rationale.trim(),
            refs,
            fragile: kind === "shared" ? fragile : false,
            constraints: kind === "shared" ? args.constraints?.trim() || null : null,
            suggested_target:
              kind === "consolidations" ? args.suggested_target?.trim() || null : null,
            group: args.group || "misc",
            status: "pending", // pending | merged | rejected (user/nvim sets this)
          };
          appendPending(directory, sessionID, entry);
          return JSON.stringify(
            {
              ok: true,
              message:
                `Registry proposal recorded (${kind}) for ${paths.join(", ")} — ` +
                "pending review. Nothing was written to the registry; accept " +
                "via the review console to merge.",
              entry_id: entry.ts,
              queue: registryPendingFile(directory),
            },
            null,
            2,
          );
        },
      }),
    },
  };
};

export default ManagePlugin;
